update_rule.pseudocode:
if day == 0:
  if network_type == 'small_world':
    G = watts_strogatz_graph(n=population_size, k=average_degree, p=network_rewire_prob, seed=seed)
  elif network_type == 'erdos_renyi':
    G = erdos_renyi_graph(n=population_size, p=average_degree/(population_size-1), seed=seed)
  assign contacts to each Person from G

mandate_active = (day >= policy_mandate_day) and (day <= policy_end_day)
for each Location L:
  if mandate_active:
    budget_per_loc = enforcement_budget / (location_count_home + location_count_work + location_count_public)
    for each Person i present at L:
      if i.adoption_state == 0:
        enforce_p = enforcement_probability * L.enforcement_level * L.policy_strictness
        if Bernoulli(enforce_p):
          if entry_denial_prob > 0 and Bernoulli(entry_denial_prob):
            i.compliance_event = (i.mask_inventory > 0)
            if i.compliance_event: i.adoption_state = 1
          else:
            apply_penalty(i, penalty_amount)
            if on_site_mask_purchase_allowed and i.mask_inventory == 0:
              trigger_purchase_request(i)
